def has_close_elements(numbers: List[float], threshold: float) -> bool:
    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point):
    def is_covered(carpet, point):
        a, b, g, k = carpet
        return a <= point[0] <= a + g and b <= point[1] <= b + k

    for i in range(n - 1, -1, -1):
        if is_covered(carpets[i], point):
            return i
    return -1

