def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):

    # Initialize matrix to count the number of chatting pairs that can be separated by adding an aisle
    count_matrix = [[0] * (N + L) for _ in range(M + K)]

    # Loop through chatting pairs and count the number of pairs that can be separated in each position
    for pair in chatting_pairs:
        for i in range(M + K):
            for j in range(N + L):
                if pair[0] == i and pair[1] < j < pair[1] + L:
                    count_matrix[i][j] += 1
                if pair[0] < i < pair[0] + K and pair[1] == j:
                    count_matrix[i][j] += 1

    # Find the maximum count in each row and column
    max_rows = [max(row) for row in count_matrix]
    max_cols = [max(col) for col in zip(*count_matrix)]

    # Select the most effective positions for aisles
    row_aisles = [i for i, count in enumerate(max_rows) if count > 0]
    col_aisles = [i for i, count in enumerate(max_cols) if count > 0]

    return ' '.join(str(i) for i in row_aisles), ' '.join(str(i) for i in col_aisles)

def count_passing_ways(n: int, m: int) -> int:
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1
    for i in range(1, n):
        dp[i][0] = 1
    for j in range(1, m + 1):
        for i in range(n):
            if i - 1 >= 0:
                dp[i][j] += dp[i - 1][j - 1]
            if i + 1 < n:
                dp[i][j] += dp[i + 1][j - 1]
    return dp[0][-1]

