def select_volunteers(n, m, applicants):
    # Sort the applicants by test score in descending order
    sorted_applicants = sorted(applicants, key=lambda x: x[1], reverse=True)

    # Calculate the interview score cutoff
    interview_score_cutoff = m * 1.5

    # Identify qualified applicants
    qualified_applicants = []
    for applicant in sorted_applicants:
        if applicant[1] >= interview_score_cutoff:
            qualified_applicants.append(applicant)

    return (interview_score_cutoff, qualified_applicants)

def decode(encoded, original, message):
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(encoded)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        elif mapping[encoded[i]] != original[i]:
            return "Failed"
    # Use the mapping to decode the message
    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            decoded += char
    return decoded

def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    if n == last:
        return 1
    total = 0
    for i in range(n, last):
        if i <= last // 2:
            total += count_sequences(n, i, memo)
    memo[last] = total
    return total

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        if y0 % (a * x0) == 0:
            b = y0 // (a * x0)
            if a == b:
                count += 1
            elif all(x0 % i for i in range(2, int(sqrt(a)) + 1)) and all(x0 % i for i in range(2, int(sqrt(b)) + 1)):
                count += 2
    return count

def preorder_traversal(inorder, postorder):
    inorder_idx = {c: i for i, c in enumerate(inorder)}
    postorder_idx = {c: i for i, c in enumerate(postorder)}
    n = len(inorder)
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if inorder_idx[postorder[j]] > inorder_idx[postorder[i]]:
                graph[i].append(j)
                break
    return preorder_traversal_helper(graph, 0, [])

def preorder_traversal_helper(graph, node, visited):
    if node == len(graph):
        return ""
    visited.append(node)
    result = ""
    for neighbor in graph[node]:
        if neighbor not in visited:
            result += preorder_traversal_helper(graph, neighbor, visited)
    result += str(node)
    return result

def is_prime(num: int) -> bool:
    """Determine whether a given integer is a prime number."""
    if num <= 1:
        return False
    if num in (2, 3):
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    for i in range(5, int(num ** 0.5) + 1, 6):
        if num % i == 0 or num % (i + 2) == 0:
            return False
    return True

def generate_numbers(n, rules):
    visited = set()
    queue = [n]
    count = 0
    while queue:
        current = queue.pop(0)
        if current not in visited:
            visited.add(current)
            count += 1
            for rule in rules:
                x, y = rule
                next = current.replace(str(x), str(y))
                if next not in visited:
                    queue.append(next)
    return count

def check_scenario(scenario, liar_count, statements, days_of_week):
    # Check if the scenario participant is a liar
    if scenario in liar_count:
        # If the scenario participant is a liar, we need to invert the statements
        # For example, if the scenario is "I am not guilty.", we need to check if the other participants said "I am guilty."
        for participant, statement in statements.items():
            if participant != scenario and statement[0] == "I am not guilty.":
                # Invert the statement and check if it matches the scenario participant's statement
                inverted_statement = "I am guilty." if statement[0] == "I am not guilty." else "I am not guilty."
                if participant in statements and statements[participant][0] == inverted_statement:
                    return True
        return False
    else:
        # If the scenario participant is not a liar, we can simply check if the statements match
        for participant, statement in statements.items():
            if participant != scenario and statement[0] != "I am guilty.":
                return False
        return True

def calculate_score(system: int, points: str) -> list:
    """
    Calculate the score of a series of ping-pong games based on the provided scoring system.

    Args:
        system (int): The number of points required to win a game (either 11 or 21).
        points (str): A string of 'W' and 'L' characters denoting points won by the player and opponent.

    Returns:
        list: A list of strings representing the score of each game.
    """
    player_score = 0
    opponent_score = 0
    scores = []
    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1
        else:
            raise ValueError("Invalid point value, must be 'W' or 'L'")
        if (player_score >= system and player_score > opponent_score + 2) or (opponent_score >= system and opponent_score > player_score + 2):
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0
    if points[-1] == 'W':
        player_score += 1
    elif points[-1] == 'L':
        opponent_score += 1
    if player_score >= 11:
        scores.append(f"{player_score}:{opponent_score}")
    elif opponent_score >= 11:
        scores.append(f"{player_score}:{opponent_score}")
    return scores

def catalan_number(n: int) -> int:
    if n == 0:
        return 1
    return sum(catalan_number(i) * catalan_number(n-i-1) for i in range(n))

def min_remaining_space(V, n, volumes):
    # Initialize a dynamic programming table to store the maximum volume that can be occupied
    # by any subset of the given items.
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill the table with the values from the given capacities.
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            dp[i][j] = max(dp[i - 1][j], volumes[i - 1] + dp[i - 1][j - volumes[i - 1]])

    # Return the difference between the box's total capacity and the maximum occupied volume.
    return V - dp[n][V]

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [1] + [0] * m
    for i in range(1, n+1):
        for j in range(m, 0, -1):
            if j >= a[i-1]:
                dp[j] = (dp[j] + dp[j-a[i-1]]) % MOD
    return dp[m]

def find_most_unhappy_day(schedule):
    total_hours = [school_hours + extra_class_hours for school_hours, extra_class_hours in schedule]
    max_total_hours = max(total_hours)
    if max_total_hours <= 8:
        return 0
    else:
        return total_hours.index(max_total_hours) + 1

